class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        if len(s) > 1 and len(set(s)) == 1:
            return len(s) * self.lengthAfterTransformations(s[0], t)
        count = [0] * 26
        for ch in s:
            count[ord(ch) - 97] += 1
        for _ in range(t):
            nxt = [0] * 26
            for i in range(25):
                nxt[i + 1] = count[i]
            nxt[0] = count[25]
            nxt[1] = (nxt[1] + count[25]) % mod
            count = nxt
        return sum(count) % mod
